script.setup:
// d3-contour runs marching squares over an animated height field every frame; the scene fills
// the bands between isolines (hypsometric tint) and draws the lines on top.
const { contours } = await ctx.utils.import("https://esm.sh/d3-contour@4.0.2");
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const flat = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec4 a_color;
uniform vec2 u_px; out vec4 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position / u_px * 2.0 - 1.0, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor;
void main(){ outColor = v_color; }`);
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 24, 8);
gl.bindVertexArray(null);
const kit = {
  // Draws a flat (x, y, r, g, b, a) triangle list.
  draw(arr) {
    if (!arr.length) return;
    gl.useProgram(flat);
    ctx.utils.setUniforms(flat, { u_px: ctx.resolution });
    gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(arr), gl.DYNAMIC_DRAW);
    gl.drawArrays(gl.TRIANGLES, 0, arr.length / 6);
    gl.bindVertexArray(null);
  },
  // Signed triangle fan: inside a closed ring the triangles add up to ±c, outside they cancel.
  // Summed with additive blending, this fills any polygon (holes, self-overlaps) exactly.
  fan(ring, c, out) {
    const x0 = ring[0], y0 = ring[1];
    for (let i = 2; i + 3 < ring.length; i += 2) {
      const s = Math.sign((ring[i] - x0) * (ring[i + 3] - y0) - (ring[i + 1] - y0) * (ring[i + 2] - x0));
      if (!s) continue;
      out.push(x0, y0, c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i], ring[i + 1], c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i + 2], ring[i + 3], c[0] * s, c[1] * s, c[2] * s, c[3] * s);
    }
  },
  // Thick polyline as quads (WebGL lines are 1 px); square ends overlap at the joints.
  line(pts, closed, width, c, out) {
    const n = pts.length / 2, hw = width / 2;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const j = (i + 1) % n;
      const ax = pts[i * 2], ay = pts[i * 2 + 1], bx = pts[j * 2], by = pts[j * 2 + 1];
      const len = Math.hypot(bx - ax, by - ay);
      if (len < 1e-6) continue;
      const dx = (bx - ax) / len * hw, dy = (by - ay) / len * hw;
      const p = [ax - dx - dy, ay - dy + dx, ax - dx + dy, ay - dy - dx, bx + dx + dy, by + dy - dx, bx + dx - dy, by + dy + dx];
      for (const k of [0, 1, 2, 0, 2, 3]) out.push(p[k * 2], p[k * 2 + 1], c[0], c[1], c[2], c[3]);
    }
  },
  // Disc made of triangles.
  dot(x, y, r, c, out, seg = 16) {
    for (let i = 0; i < seg; i++) {
      const a0 = i / seg * 6.2832, a1 = (i + 1) / seg * 6.2832;
      out.push(x, y, ...c, x + Math.cos(a0) * r, y + Math.sin(a0) * r, ...c, x + Math.cos(a1) * r, y + Math.sin(a1) * r, ...c);
    }
  },
  acc: null,
  // Renders signed fans additively into a half-float target at up to 2x the canvas size
  // (sampling it back with linear filtering smooths the edges). Returns the texture.
  accumulate(arr) {
    const [w, h] = ctx.resolution, k = Math.min(2, 4096 / Math.max(w, h));
    const tw = Math.round(w * k), th = Math.round(h * k);
    if (!kit.acc) kit.acc = ctx.utils.createPingPong(tw, th, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT });
    else if (kit.acc.width !== tw || kit.acc.height !== th) kit.acc.resize(tw, th);
    const t = kit.acc.read();
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer); gl.viewport(0, 0, tw, th);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
    kit.draw(arr);
    gl.disable(gl.BLEND);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
    return t.texture;
  },
};
const s = ctx.state;
s.kit = kit; s.contours = contours;
// A few drifting sine waves in random directions, summed and warped: smooth, noise-like terrain.
s.waves = Array.from({ length: 8 }, (_, i) => {
  const a = Math.random() * 6.283, f = 3 + i * 1.5;
  return { fx: Math.cos(a) * f, fy: Math.sin(a) * f, w: 0.2 + Math.random() * 0.4, ph: Math.random() * 6.283, amp: 1 / (1 + i * 0.45) };
});
s.composite = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_bands; uniform sampler2D u_field; uniform float u_levels; uniform vec2 u_cell;
uniform vec3 u_low; uniform vec3 u_mid; uniform vec3 u_high;
vec3 tint(float k){
  float t = k / u_levels;
  return t < 0.5 ? mix(u_low, u_mid, t * 2.0) : mix(u_mid, u_high, t * 2.0 - 1.0);
}
void main(){
  float b = abs(texture(u_bands, v_uv).r);
  vec3 c = mix(tint(floor(b)), tint(floor(b) + 1.0), fract(b));
  // Hill shading from the field's gradient (light from the upper left).
  vec2 f = vec2(v_uv.x, 1.0 - v_uv.y);
  float gx = texture(u_field, f + vec2(u_cell.x, 0.0)).r - texture(u_field, f - vec2(u_cell.x, 0.0)).r;
  float gy = texture(u_field, f - vec2(0.0, u_cell.y)).r - texture(u_field, f + vec2(0.0, u_cell.y)).r;
  float shade = clamp(0.85 + (-gx + gy) * 2.5, 0.55, 1.25);
  outColor = vec4(c * shade, 1.0);
}`);
s.fieldTex = null;
s.moved = false;

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, kit = s.kit;
const [w, h] = ctx.resolution;
const n = 128, m = Math.max(8, Math.round(n * h / w));
if (!s.values || s.values.length !== n * m) { s.values = new Float32Array(n * m); s.fieldTex = null; }
const t = ctx.time * u.u_speed;
const [mx, my] = ctx.mouse;
s.moved ||= mx !== 0.5 || my !== 0.5;
const aspect = w / h;
for (let j = 0; j < m; j++) for (let i = 0; i < n; i++) {
  const x = (i + 0.5) / n * aspect, y = (j + 0.5) / m;
  // Domain warp: bend the coordinates with one wave before summing the rest.
  const wx = x + 0.12 * Math.sin(y * 3.1 + t * 0.7), wy = y + 0.12 * Math.cos(x * 2.7 - t * 0.5);
  let v = 0;
  for (const q of s.waves) v += Math.sin(wx * q.fx + wy * q.fy + t * q.w + q.ph) * q.amp;
  v = Math.tanh(v * u.u_relief / 1.7); // keeps peaks inside the threshold range
  if (s.moved) {
    // The pointer raises a hill (y down in both the grid and ctx.mouse).
    const dx = x - mx * aspect, dy = y - my;
    v += u.u_hill * Math.exp(-(dx * dx + dy * dy) / 0.03);
  }
  s.values[i + j * n] = v;
}
const L = u.u_levels, thresholds = Array.from({ length: L }, (_, k) => -1 + 2 * (k + 1) / (L + 1));
const polys = s.contours().size([n, m]).thresholds(thresholds)(s.values);
// Grid → pixels (grid y runs down, pixels up).
const toPx = (ring) => { const out = []; for (const [x, y] of ring) out.push(x / n * w, h - y / m * h); return out; };
const fills = [], lines = [];
const lw = Math.max(1, h * 0.0022), dark = u.u_line;
polys.forEach((mp, k) => {
  const major = (k + 1) % 4 === 0;
  for (const poly of mp.coordinates) for (const ring of poly) {
    const pts = toPx(ring);
    kit.fan(pts, [1, 0, 0, 0], fills);
    kit.line(pts, true, major ? lw * 2.2 : lw, [dark[0], dark[1], dark[2], major ? 0.85 : 0.5], lines);
  }
});
const bands = kit.accumulate(fills);
gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
s.fieldTex = ctx.utils.uploadDataTexture(gl, s.fieldTex, n, m, s.values, { internalFormat: gl.R16F, format: gl.RED, type: gl.FLOAT, filter: gl.LINEAR, forceRealloc: !s.fieldTex });
gl.useProgram(s.composite);
ctx.utils.bindTexture(s.composite, "u_bands", bands, 0);
ctx.utils.bindTexture(s.composite, "u_field", s.fieldTex, 1);
ctx.utils.drawFullscreen(s.composite, { u_levels: L, u_cell: [1 / n, 1 / m] });
gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
kit.draw(lines);
gl.disable(gl.BLEND);
ctx.publish("isolines", polys.reduce((a, p) => a + p.coordinates.reduce((b, q) => b + q.length, 0), 0));
